 async function googleCalendarAction(action:"authorize"|"sync"|"disconnect"){
  if(!supabase)return;
  if(action==="disconnect"&&!window.confirm("Disconnect Google Calendar? Your Value Time timetable entries will remain in Value Time."))return;
  setGoogleCalendarBusy(true);setErr("");setMsg("");
  try{
   const {data,error}=await supabase.functions.invoke("google-calendar",{body:{action}});
   if(error)throw new Error(error.message);
   if(data?.error)throw new Error(data.error);
   if(action==="authorize"){
    if(!data?.authUrl)throw new Error("Google did not return a connection link.");
    window.location.assign(data.authUrl);return;
   }
   if(action==="disconnect"){setGoogleCalendar({connected:false});setMsg("Google Calendar disconnected. Your Value Time timetable was not deleted.");}
   if(action==="sync"){
    setGoogleCalendar((current:any)=>({...current,connected:true,lastSyncedAt:data.lastSyncedAt}));
    setMsg("Calendar sync complete: "+data.imported+" imported, "+data.exported+" sent to Google, "+data.updated+" updated, "+data.cancelled+" cancellations applied."+(data.skippedAllDay?" "+data.skippedAllDay+" all-day events skipped.":""));
   }
  }catch(error){setErr(error instanceof Error?error.message:"Google Calendar action failed.");}
  setGoogleCalendarBusy(false);
 }
 async function notify(){if("Notification"in window){const p=await Notification.requestPermission();setMsg("Browser notifications: "+p)}else setErr("This browser does not support notifications.")}
 async function enableBackgroundPush(){
  if(!supabase)return;
  if(!("serviceWorker"in navigator)||!("PushManager"in window)||!("Notification"in window)){setErr("This browser does not support background push notifications. Try the latest Chrome or Edge over HTTPS.");return;}
  if(!uid){setErr("Sign in again before enabling notifications.");return;}
  setBusy(true);setErr("");setMsg("");
  try{
   const permission=await Notification.requestPermission();
   if(permission!=="granted")throw new Error("Notification permission was not granted. Enable notifications in your browser settings and try again.");
   const registration=await navigator.serviceWorker.register("/sw.js");
   await navigator.serviceWorker.ready;
   const publicKey="BGaE34rSjkHec2lx_Xewd7ZDNalvLzRPtj_59t8-8uxoFII4yApwZH15muyBazGqN9sUtEUkQg-DPfDdlbs5SoQ";
   const padding="=".repeat((4-publicKey.length%4)%4);
   const raw=atob(publicKey.replace(/-/g,"+").replace(/_/g,"/")+padding);
   const applicationServerKey=Uint8Array.from(raw,ch=>ch.charCodeAt(0));
   let subscription=await registration.pushManager.getSubscription();
   if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey});
   const json=subscription.toJSON();
   if(!json.keys?.p256dh||!json.keys?.auth)throw new Error("The browser did not provide the required push encryption keys.");
   const saved=await supabase.from("push_subscriptions").upsert({user_id:uid,endpoint:subscription.endpoint,p256dh:json.keys.p256dh,auth_secret:json.keys.auth,expiration_time:subscription.expirationTime,user_agent:navigator.userAgent},{onConflict:"endpoint"});
   if(saved.error)throw new Error(saved.error.message);
   const pref=await supabase.from("user_preferences").update({push_enabled:true}).eq("user_id",uid);
   if(pref.error)throw new Error(pref.error.message);
   setPrefs({...prefs,push_enabled:true});setMsg("Background push is registered on this device. Delivery will begin once the reminder Worker VAPID secrets are configured.");
  }catch(error){setErr(error instanceof Error?error.message:"Could not enable background push notifications.");}
  setBusy(false);
 }
