   const backup={product:"Value Time",format_version:1,exported_at:new Date().toISOString(),profile:profileResult.data,tables:Object.fromEntries(tables.map((table,index)=>[table,tableResults[index].data||[]])),notice:"This backup contains database records and attachment paths. Download uploaded assignment files separately from the Assignments section."};
